int Trace(string text, int value) { Print(text); return value; }
class Field {
 public static int Value = Trace("field-init", 1);
}
class Property {
 static int stored = Trace("property-init", 2);
 public static int Value { get { Print("get"); return stored; } set { Print("set:" + value); stored = value + 1; value = 99; } }
}
class Method {
 static Method() { Print("method-init"); }
 public static int Add(int a, int b) => a + b;
}
void Main() {
 Field.Value = Trace("field-rhs", 5); Print(Field.Value);
 Print(Property.Value = Trace("property-rhs", 6)); Print(Property.Value);
 Print(Property.Value += Trace("compound-rhs", 3)); Print(Property.Value++); Print(Property.Value);
 Print(Method.Add(b: Trace("b", 2), a: Trace("a", 1)));
}
